    cardTags:['Blackjack','Rules · guide'],cardTitle:'How to play blackjack: rules and card values',cardDescription:'Actions, soft 17, 3:2 payouts, and a full sample hand—no casino fog, just the rules.',cardRead:'Read the article →',cardDate:'Published: September 7, 2026'
